import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import {
  getConfirmedCanonicalHost,
  getSiteCanonicalHost,
  validateProductionCanonicalHost,
  WORKING_DOMAIN_CANDIDATE,
} from '../../src/utils/seo';

const projectRoot = path.resolve(__dirname, '../../');
const distDir = path.join(projectRoot, 'dist');

// The known published indexable HTML files generated by Astro static build
const publishedPageFiles = [
  'index.html',
  'abonnement-iptv/index.html',
  'appareils-compatibles/index.html',
  'assistance/index.html',
  'assistance/iptv-buffering/index.html',
  'blog/comment-choisir-abonnement-iptv/index.html',
];

describe('Technical SEO Infrastructure (Canonicals, Metadata, Sitemap, Robots)', () => {
  const originalEnv = process.env;

  beforeEach(() => {
    process.env = { ...originalEnv };
  });

  afterEach(() => {
    process.env = originalEnv;
  });

  it('Test 1: Every published indexable page has exactly one title', () => {
    for (const pageRelPath of publishedPageFiles) {
      const fullPath = path.join(distDir, pageRelPath);
      expect(fs.existsSync(fullPath), `${pageRelPath} must exist in dist/`).toBe(true);

      const html = fs.readFileSync(fullPath, 'utf-8');
      const titleMatches = html.match(/<title\b[^>]*>([\s\S]*?)<\/title>/gi);

      expect(titleMatches, `Page ${pageRelPath} must have a <title> tag`).not.toBeNull();
      expect(titleMatches!.length, `Page ${pageRelPath} must have exactly one <title>`).toBe(1);

      const titleText = titleMatches![0].replace(/<[^>]*>/g, '').trim();
      expect(titleText.length, `Title of ${pageRelPath} must not be empty`).toBeGreaterThan(10);
      expect(titleText).toContain('NexaTV');
    }
  });

  it('Test 2: Every published indexable page has a unique meta description', () => {
    const descriptions = new Map<string, string>();

    for (const pageRelPath of publishedPageFiles) {
      const fullPath = path.join(distDir, pageRelPath);
      const html = fs.readFileSync(fullPath, 'utf-8');

      // Match content="..." or content='...'
      const descMatches = html.match(/<meta\b[^>]*name=["']description["'][^>]*content="([^"]*)"/i)
        || html.match(/<meta\b[^>]*name=["']description["'][^>]*content='([^']*)'/i);
      expect(descMatches, `Page ${pageRelPath} must have a meta description tag`).not.toBeNull();

      const description = descMatches![1].trim();
      expect(description.length, `Description for ${pageRelPath} must be at least 30 chars`).toBeGreaterThan(30);

      // Verify uniqueness across pages to avoid cannibalization
      for (const [otherPage, otherDesc] of descriptions.entries()) {
        expect(
          description,
          `Page ${pageRelPath} duplicate description with ${otherPage}`
        ).not.toBe(otherDesc);
      }

      descriptions.set(pageRelPath, description);
    }
  });

  it('Test 3: Every published indexable page has exactly one absolute canonical link', () => {
    for (const pageRelPath of publishedPageFiles) {
      const fullPath = path.join(distDir, pageRelPath);
      const html = fs.readFileSync(fullPath, 'utf-8');

      const canonicalMatches = html.match(/<link\b[^>]*rel=["']canonical["'][^>]*href=["']([^"']*)["'][^>]*>/gi);
      expect(canonicalMatches, `Page ${pageRelPath} must have a canonical tag`).not.toBeNull();
      expect(canonicalMatches!.length, `Page ${pageRelPath} must have exactly one canonical link`).toBe(1);

      const hrefMatch = canonicalMatches![0].match(/href=["']([^"']*)["']/i);
      const canonicalHref = hrefMatch![1];

      // Must be an absolute URL
      expect(canonicalHref).toMatch(/^https?:\/\//);
      // Must end with a trailing slash
      expect(canonicalHref.endsWith('/')).toBe(true);
    }
  });

  it('Test 4: Canonical host matches confirmed production configuration and fails if unconfigured', () => {
    // When no confirmed production host is configured
    delete process.env.PUBLIC_SITE_URL;
    delete process.env.SITE_URL;

    expect(() => getConfirmedCanonicalHost()).toThrow(/canonical host is unknown/i);
    expect(() => validateProductionCanonicalHost()).toThrow(/canonical host is unknown/i);

    // Fallback in candidate mode returns working domain candidate
    expect(getSiteCanonicalHost()).toBe(WORKING_DOMAIN_CANDIDATE);

    // When configured with a valid confirmed host
    process.env.PUBLIC_SITE_URL = 'https://nexatv.fr';
    expect(getConfirmedCanonicalHost()).toBe('https://nexatv.fr');
    expect(() => validateProductionCanonicalHost()).not.toThrow();
  });

  it('Test 5: Sitemap excludes unpublished guides', () => {
    const sitemapPath = path.join(distDir, 'sitemap.xml');
    expect(fs.existsSync(sitemapPath), 'dist/sitemap.xml must exist').toBe(true);

    const sitemapXml = fs.readFileSync(sitemapPath, 'utf-8');
    expect(sitemapXml).not.toContain('/guides/installer-iptv-samsung/');
    expect(sitemapXml).not.toContain('installer-iptv-samsung');
  });

  it('Test 6: Sitemap excludes drafts and noncanonical variants', () => {
    const sitemapPath = path.join(distDir, 'sitemap.xml');
    const sitemapXml = fs.readFileSync(sitemapPath, 'utf-8');

    // Only published routes are included
    expect(sitemapXml).toContain('/abonnement-iptv/</loc>');
    expect(sitemapXml).toContain('/appareils-compatibles/</loc>');
    expect(sitemapXml).toContain('/assistance/</loc>');
    expect(sitemapXml).toContain('/assistance/iptv-buffering/</loc>');
    expect(sitemapXml).toContain('/blog/comment-choisir-abonnement-iptv/</loc>');

    // No duplicate blog route for buffering
    expect(sitemapXml).not.toContain('/blog/iptv-buffering/</loc>');

    // No draft or test routes
    expect(sitemapXml).not.toContain('/draft');
    expect(sitemapXml).not.toContain('status=draft');
  });

  it('Test 7: All URLs in sitemap resolve to existing static HTML pages', () => {
    const sitemapPath = path.join(distDir, 'sitemap.xml');
    const sitemapXml = fs.readFileSync(sitemapPath, 'utf-8');

    const locMatches = sitemapXml.match(/<loc>([^<]+)<\/loc>/g);
    expect(locMatches).not.toBeNull();
    expect(locMatches!.length).toBe(6);

    for (const locTag of locMatches!) {
      const url = locTag.replace(/<\/?loc>/g, '').trim();
      const urlObj = new URL(url);
      const relPath = urlObj.pathname === '/' ? 'index.html' : `${urlObj.pathname.replace(/^\/|\/$/g, '')}/index.html`;

      const expectedFile = path.join(distDir, relPath);
      expect(fs.existsSync(expectedFile), `Sitemap URL ${url} must exist at ${expectedFile}`).toBe(true);
    }
  });

  it('Test 8: robots.txt exists, specifies sitemap, and does not block essential rendering resources', () => {
    const robotsPath = path.join(distDir, 'robots.txt');
    expect(fs.existsSync(robotsPath), 'dist/robots.txt must exist').toBe(true);

    const robotsTxt = fs.readFileSync(robotsPath, 'utf-8');

    expect(robotsTxt).toContain('User-agent: *');
    expect(robotsTxt).toContain('Allow: /');
    expect(robotsTxt).toMatch(/Sitemap:\s*https?:\/\/[^\s]+\/sitemap\.xml/);

    // Does not block CSS, images or _astro scripts
    expect(robotsTxt).not.toMatch(/Disallow:\s*\/_astro/);
    expect(robotsTxt).not.toMatch(/Disallow:\s*\*\.css/);
    expect(robotsTxt).not.toMatch(/Disallow:\s*\*\.svg/);
  });

  it('Test 9: Homepage and pricing page have distinct metadata and intents', () => {
    const homeHtml = fs.readFileSync(path.join(distDir, 'index.html'), 'utf-8');
    const pricingHtml = fs.readFileSync(path.join(distDir, 'abonnement-iptv/index.html'), 'utf-8');

    const homeTitle = homeHtml.match(/<title>([^<]+)<\/title>/)![1];
    const pricingTitle = pricingHtml.match(/<title>([^<]+)<\/title>/)![1];
    expect(homeTitle).not.toBe(pricingTitle);

    const homeDesc = homeHtml.match(/<meta\b[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i)![1];
    const pricingDesc = pricingHtml.match(/<meta\b[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i)![1];
    expect(homeDesc).not.toBe(pricingDesc);

    // Intent distinction
    expect(homeTitle).toContain('dès 12 €');
    expect(pricingTitle).toContain('nos formules 3, 6 et 12 mois');
  });

  it('Test 10: No accidental near-duplicate commercial routes are generated', () => {
    const forbiddenRoutes = [
      'dist/abonnement-iptv-12-mois/index.html',
      'dist/abonnement-iptv-pas-cher/index.html',
      'dist/iptv-france/index.html',
      'dist/meilleur-iptv/index.html',
      'dist/iptv-paris/index.html',
    ];

    for (const route of forbiddenRoutes) {
      expect(
        fs.existsSync(path.join(projectRoot, route)),
        `Near-duplicate route ${route} must NOT exist`
      ).toBe(false);
    }
  });
});
